import unittest

from src.pricing_percent import apply
from src.invoice import invoice_total
from src.customer import customer_total
from src.analytics_fraction import apply as analytics


class PricingPercentRegressionTests(unittest.TestCase):
    def test_percent_units_and_rounding_for_every_caller(self):
        for total in (apply, invoice_total, customer_total):
            for amount, percent, expected in (
                (100, 10, 90),
                (200, 25, 150),
                (100, 0, 100),
                (100, 100, 0),
                (100, 0.1, 99.9),
                (123.45, 12.5, 108.02),
            ):
                with self.subTest(total=total.__name__, percent=percent):
                    self.assertEqual(total(amount, percent), expected)

    def test_validation_is_preserved_through_every_caller(self):
        for total in (apply, invoice_total, customer_total):
            for percent in (-0.1, 100.1, float("nan")):
                with self.subTest(total=total.__name__, percent=percent):
                    with self.assertRaisesRegex(ValueError, "^percent out of range$"):
                        total(100, percent)
            with self.subTest(total=total.__name__, percent="10"):
                with self.assertRaises(TypeError):
                    total(100, "10")

    def test_fraction_api_keeps_its_own_units(self):
        self.assertEqual(analytics(100, 0.1), 90)
        self.assertEqual(apply(100, 0.1), 99.9)


if __name__ == "__main__":
    unittest.main()

